.mohonCTA{display:flex;align-items:center;gap:12px;margin-top:12px;padding:14px;border-radius:16px;cursor:pointer;color:#fff;background:linear-gradient(120deg,#f59e0b,#f97316 55%,#ea580c);box-shadow:0 10px 24px -10px rgba(234,88,12,.7);position:relative;overflow:hidden;animation:naik .4s ease both}
.mohonCTA:after{content:"";position:absolute;top:0;left:-60%;width:40%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.45),transparent);animation:kilat 3s ease-in-out infinite;pointer-events:none}
@keyframes kilat{0%,60%{left:-60%}100%{left:130%}}
.mohonCTA .ic{width:44px;height:44px;border-radius:12px;background:rgba(255,255,255,.22);display:flex;align-items:center;justify-content:center;font-size:24px;flex:none}
.mohonCTA .tx{flex:1;text-align:left}.mohonCTA b{display:block;font-size:14.5px;line-height:1.25}.mohonCTA small{font-size:12px;opacity:.92}
.mohonCTA .go{background:#fff;color:#c2410c;font-weight:800;font-size:12.5px;padding:7px 12px;border-radius:999px;flex:none}
.mohonHd{display:flex;align-items:center;gap:12px;margin:-4px 0 14px;padding:14px;border-radius:14px;color:#fff;background:linear-gradient(120deg,#f59e0b,#ea580c)}
.mohonHd .ic{width:48px;height:48px;border-radius:12px;background:rgba(255,255,255,.22);display:flex;align-items:center;justify-content:center;font-size:26px;flex:none}
.mohonHd h2{margin:0;color:#fff;font-size:19px}.mohonHd p{margin:2px 0 0;font-size:13px;opacity:.95}
.mohonStep{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px}.mohonStep div{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412;border-radius:12px;padding:10px 6px;text-align:center;font-size:12.5px;font-weight:700}
.mohonStep b{display:flex;width:24px;height:24px;margin:0 auto 5px;border-radius:50%;background:#ea580c;color:#fff;align-items:center;justify-content:center;font-size:12px}
.terma{border:1.5px solid #fed7aa;background:#fffaf3;border-radius:14px;padding:12px 14px;margin:4px 0 12px}.termaH{font-weight:800;color:#9a3412;font-size:14px;margin-bottom:6px}
.terma ol{margin:0;padding-left:20px;font-size:13px;line-height:1.55;color:var(--ink)}.terma li{margin:3px 0}
.cbOl{margin:4px 0;padding-left:20px;line-height:1.5}
.lapor.mohonB{margin-top:10px}
